import sys

def is_poligrama(s, L):
    n = len(s)
    alvo = [0] * 26
    for ch in s[:L]:
        alvo[ord(ch) - ord('a')] += 1

    for i in range(L, n, L):
        cnt = [0] * 26
        for ch in s[i:i + L]:
            cnt[ord(ch) - ord('a')] += 1
        if cnt != alvo:
            return False

    return True

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    s = data[1]

    for L in range(1, n):
        if n % L == 0 and is_poligrama(s, L):
            print(s[:L])
            return

    print("*")

if __name__ == "__main__":
    main()
